/** Renders integer cents as dollars (see SPEC.md). */
export function formatCents(cents: number): string {
	const dollars = Math.floor(cents / 100);
	const rest = cents % 100;
	return '$' + dollars + '.' + rest;
}

/** Renders a receipt (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	const sum = lines.reduce((total, line) => total + line.cents, 0);
	const itemLines = lines.map((line) => `${line.label}: ${formatCents(line.cents)}`);
	return [...itemLines, `Total: ${formatCents(sum)}`].join('\n');
}

